class Solution:
    def maxPathSum(self, root):
        def helper(node):
            if not node:
                return float('-inf')
            if not node.left and not node.right:
                return node.data
            left_sum = helper(node.left)
            right_sum = helper(node.right)
            return node.data + max(left_sum, right_sum)

        return helper(root)
